package dev.sigmarix.quests.client;
import dev.sigmarix.quests.*;
import java.util.*;import java.util.function.*;import java.lang.reflect.Field;
import net.minecraft.client.gui.*;import net.minecraft.item.*;import net.minecraft.util.StatCollector;
/** Typed original property forms. Changes remain in a private book until accepted. */
final class QuestObjectConfigScreen extends QuestConfigScreen {
    final QuestCore.Book draft;final Object object;final String scope;final Runnable commit;private final boolean validateAll;private final GuiScreen parentScreen;private boolean quick;
    QuestObjectConfigScreen(GuiScreen parent,QuestCore.Book draft,Object object,String scope,Runnable commit){this(parent,draft,object,scope,commit,true);}
    QuestObjectConfigScreen(GuiScreen parent,QuestCore.Book draft,Object object,String scope,Runnable commit,boolean validateAll){super(parent);this.draft=draft;this.object=object;this.scope=scope;this.commit=commit;this.validateAll=validateAll;this.parentScreen=parent;}
    static void edit(GuiScreen parent,String questId,String collection,String id){net.minecraft.client.Minecraft.getMinecraft().displayGuiScreen(prepare(parent,questId,collection,id));}
    static QuestObjectConfigScreen prepare(GuiScreen parent,String questId,String collection,String id){
        final QuestCore.Book book=QuestService.JSON.fromJson(QuestService.JSON.toJson(ClientProxy.snapshot.book),QuestCore.Book.class);Object object=book;String scope="file";
        if(questId.startsWith("chapter:")){for(QuestCore.Chapter c:book.chapters)if(c.id.equals(questId.substring(8))){object=c;scope="chapter";break;}}
        else if(!questId.isEmpty())for(QuestCore.Quest q:book.quests)if(q.id.equals(questId)){object=q;scope="quest";if(collection.equals("tasks"))for(QuestCore.Task task:q.tasks)if(task.id.equals(id)){object=task;scope="task";}if(collection.equals("rewards"))for(QuestCore.Reward reward:q.rewards)if(reward.id.equals(id)){object=reward;scope="reward";}break;}
        long revision=ClientProxy.snapshot.revision;return new QuestObjectConfigScreen(parent,book,object,scope,()->send(book,revision));
    }
    static void send(QuestCore.Book book,long revision){book.validate();QuestNetwork.Action action=new QuestNetwork.Action();action.action="save";action.book=book;action.revision=revision;ClientProxy.send(action);}
    @Override protected String title(){return "FTB Quests";}
    private String tr(String key){return StatCollector.translateToLocal(key);}
    private String prefix(){String type=object instanceof QuestCore.Task?((QuestCore.Task)object).type:object instanceof QuestCore.Reward?((QuestCore.Reward)object).type:"";if(type.equals("check"))type="checkmark";if(type.equals("xp_levels"))type="xp_levels";if(type.equals("loot"))type="random";return "ftbquests."+scope+((scope.equals("task") || scope.equals("reward"))?".ftbquests."+type:"");}
    private String label(String key){String candidate=prefix()+"."+key;return StatCollector.canTranslate(candidate)?tr(candidate):StatCollector.canTranslate("ftbquests."+key)?tr("ftbquests."+key):key;}
    private Object get(String name){try{return object.getClass().getField(name).get(object);}catch(ReflectiveOperationException e){throw new IllegalArgumentException(name,e);}}
    private void put(String name,Object value){try{Field field=object.getClass().getField(name);field.set(object,value);if(name.equals("repeatable") && object instanceof QuestCore.Quest){QuestCore.Quest q=(QuestCore.Quest)object;q.autoRepeat=q.repeatable;if(q.repeatable)q.rewardMode="team";}if(quick){draft.validate();commit.run();}}catch(ReflectiveOperationException e){throw new IllegalArgumentException(name,e);}}
    private boolean has(String name){try{object.getClass().getField(name);return true;}catch(NoSuchFieldException e){return false;}}
    private Entry scalar(String name,String key){
        return new Entry("FTB Quests",label(key),()->String.valueOf(get(name)==null?"":get(name)),()->get(name) instanceof Boolean?Boolean.TRUE.equals(get(name))?0x33AA33:0xD52834:get(name) instanceof Number?0xAA5AE8:0xFFAA49,(button,gui)->{
            Object value=get(name);if(value instanceof Boolean){put(name,!((Boolean)value));return;}int color=value instanceof Number?0xAA5AE8:0xFFAA49;
            mc.displayGuiScreen(new QuestValueScreen(this,value==null?"":String.valueOf(value),color,32768,text->{Object next=text;if(value instanceof Integer)next=Integer.valueOf(text);else if(value instanceof Long)next=Long.valueOf(text);else if(value instanceof Double)next=Double.valueOf(text);put(name,next);}));
        });
    }
    private Entry enumeration(String name,String key,String...values){return new Entry("FTB Quests",label(key),()->{String value=String.valueOf(get(name));String loc=prefix()+"."+key+"."+(value.isEmpty()?"default":value);return StatCollector.canTranslate(loc)?tr(loc):value;},()->0x0094FF,(button,gui)->{
        if(isCtrlKeyDown()){mc.displayGuiScreen(new QuestListScreen(quick?parentScreen:this,false,false,2,2,0){protected String title(){return label(key);}protected List<Row> rows(){List<Row> rows=new ArrayList<Row>();for(int i=0;i<values.length;i++)rows.add(new Row(i,values[i].isEmpty()?QuestText.tr("Default"):values[i],""));return rows;}protected void click(Row row,int mouse){put(name,values[row.id]);mc.displayGuiScreen(quick?parentScreen:QuestObjectConfigScreen.this);}});}
        else{int i=Arrays.asList(values).indexOf(String.valueOf(get(name)));put(name,values[(i+(button==0?1:values.length-1)+values.length)%values.length]);}
    });}
    @SuppressWarnings("unchecked") private Entry strings(String name,String key){return new Entry("FTB Quests",label(key),()->"["+((List<?>)get(name)).size()+"]",()->0xFFAA49,(button,gui)->mc.displayGuiScreen(new QuestValueListScreen<String>(this,label(key),(List<String>)get(name),()->"",value->value,(parent,value,accept)->mc.displayGuiScreen(new QuestValueScreen(parent,value,0xFFAA49,32768,accept)),0xFFAA49)));}
    private Entry item(String field,String meta,String nbt,String key){return new Entry("FTB Quests",label(key),()->{ItemStack stack=stack((String)get(field),((Number)get(meta)).intValue(),(String)get(nbt));return stack==null?tr("ftbquests.null"):stack.getDisplayName();},()->0x33AA33,(button,gui)->mc.displayGuiScreen(new QuestItemSelectScreen(this,stack((String)get(field),((Number)get(meta)).intValue(),(String)get(nbt)),true,s->true,s->{put(field,s==null?"":(String)Item.itemRegistry.getNameForObject(s.getItem()));put(meta,s==null?0:s.getItemDamage());put(nbt,s!=null && s.hasTagCompound()?s.getTagCompound().toString():"");})));}
    private ItemStack stack(String id,int meta,String nbt){Item item=id==null || id.startsWith("ore:")?null:(Item)Item.itemRegistry.getObject(id);if(item==null)return null;ItemStack stack=new ItemStack(item,1,Math.max(0,meta));stack.setTagCompound(QuestService.tag(nbt));return stack;}
    private List<ItemStack> taskItems(QuestCore.Task task){List<ItemStack> items=new ArrayList<ItemStack>();ItemStack first=stack(task.target,task.meta,task.nbt);if(first!=null)items.add(first);for(String id:task.targets){ItemStack next=stack(id,task.meta,task.nbt);if(next!=null)items.add(next);}filterItems(task.filter,items);return items;}
    private void filterItems(QuestItemFilter filter,List<ItemStack> items){if(filter==null)return;if(filter.type.equals("item")){ItemStack stack=stack(filter.value,filter.meta,filter.nbt);if(stack!=null)items.add(stack);}for(QuestItemFilter child:filter.children)filterItems(child,items);}
    private Entry itemList(){QuestCore.Task task=(QuestCore.Task)object;return new Entry("FTB Quests",label("items"),()->"["+taskItems(task).size()+"]",()->0x33AA33,(button,gui)->{List<ItemStack> items=taskItems(task);mc.displayGuiScreen(new QuestValueListScreen<ItemStack>(this,label("items"),items,()->null,s->s==null?tr("ftbquests.null"):s.getDisplayName(),(parent,s,accept)->mc.displayGuiScreen(new QuestItemSelectScreen(parent,s,true,v->true,accept)),0x33AA33).onAccepted(()->pendingItems=items));});}
    private List<ItemStack> pendingItems;
    @Override public void initGui(){if(pendingDescription!=null){put("description",String.join("\n",pendingDescription));pendingDescription=null;}if(pendingItems!=null){QuestCore.Task task=(QuestCore.Task)object;task.target="";task.targets.clear();task.filter=null;if(!pendingItems.isEmpty()){QuestItemFilter any=new QuestItemFilter();any.type="any";for(ItemStack s:pendingItems)if(s!=null){QuestItemFilter filter=new QuestItemFilter();filter.value=(String)Item.itemRegistry.getNameForObject(s.getItem());filter.meta=s.getItemDamage();filter.nbt=s.hasTagCompound()?s.getTagCompound().toString():"";filter.nbtMode=task.nbtMode;any.children.add(filter);}if(!any.children.isEmpty())task.filter=any;}pendingItems=null;}super.initGui();}
    private List<String> pendingDescription;
    private Entry descriptionList(){return new Entry("FTB Quests",label("description"),()->"["+(((String)get("description")).isEmpty()?0:((String)get("description")).split("\\n",-1).length)+"]",()->0xFFAA49,(button,gui)->{List<String> lines=new ArrayList<String>();String value=(String)get("description");if(!value.isEmpty())lines.addAll(Arrays.asList(value.split("\\n",-1)));mc.displayGuiScreen(new QuestValueListScreen<String>(this,label("description"),lines,()->"",v->v,(parent,v,accept)->mc.displayGuiScreen(new QuestValueScreen(parent,v,0xFFAA49,16384,accept)),0xFFAA49).onAccepted(()->pendingDescription=lines));});}
    @Override protected List<Entry> entries(){
        List<Entry> e=new ArrayList<Entry>();if(has("title"))e.add(scalar("title","title"));if(has("icon"))e.add(item("icon","iconMeta","iconNbt","icon"));if(has("tags"))e.add(strings("tags","tags"));
        if(object instanceof QuestCore.Quest){QuestCore.Quest q=(QuestCore.Quest)object;e.add(scalar("subtitle","subtitle"));e.add(descriptionList());e.add(enumeration("shape","shape","","square","rsquare","circle","diamond","pentagon","hexagon","octagon","heart","gear"));e.add(scalar("hidden","hide"));e.add(scalar("repeatable","can_repeat"));e.add(scalar("size","size"));e.add(scalar("x","x"));e.add(scalar("y","y"));e.add(scalar("optional","optional"));e.add(scalar("minWidth","min_width"));if(q.tasks.size()>1)e.add(scalar("anyTask","or_tasks"));e.add(dependencies(q));e.add(enumeration("dependencyState","dependency_requirement","completed","started"));e.add(scalar("minDependencies","min_required_dependencies"));e.add(scalar("hideDependencyLines","hide_dependency_lines"));e.add(scalar("guidePage","guide_page"));e.add(scalar("customClick","custom_click"));e.add(scalar("hideTextUntilComplete","hide_text_until_complete"));e.add(enumeration("itemBrowser","disable_jei","inherit","enabled","disabled"));}
        else if(object instanceof QuestCore.Task){QuestCore.Task t=(QuestCore.Task)object;String type=t.type;
            if(type.equals("item")){e.add(itemList());e.add(scalar("count","count"));if(t.consumeMode.equals("explicit"))t.consumeMode=t.consume?"enabled":"disabled";e.add(enumeration("consumeMode","consume_items","inherit","enabled","disabled"));e.add(scalar("ignoreDamage","ignore_damage"));e.add(enumeration("nbtMode","nbt_mode","exact","subset","ignore"));e.add(scalar("craftingOnly","only_from_crafting"));}
            else if(type.equals("fluid")){e.add(new Entry("FTB Quests",label("fluid"),()->{net.minecraftforge.fluids.Fluid fluid=net.minecraftforge.fluids.FluidRegistry.getFluid(t.target);return fluid==null?tr("ftbquests.null"):fluid.getLocalizedName(new net.minecraftforge.fluids.FluidStack(fluid,1000));},()->0x33AA33,(b,g)->mc.displayGuiScreen(new QuestFluidSelectScreen(this,false,fluid->t.target=fluid==null?"":fluid.getName()))));e.add(scalar("nbt","fluid_nbt"));e.add(scalar("count","amount"));}
            else if(type.equals("check")){}
            else if(type.equals("dimension"))e.add(scalar("dimension","dim"));
            else if(type.equals("location")){e.add(scalar("dimension","dim"));e.add(scalar("ignoreDimension","ignore_dim"));for(String name:new String[]{"x","y","z"})e.add(scalar(name,name));e.add(scalar("width","w"));e.add(scalar("height","h"));e.add(scalar("depth","d"));}
            else if(type.equals("xp")){e.add(scalar("count","value"));e.add(new Entry("FTB Quests",label("points"),()->Boolean.toString(!t.levels),()->t.levels?0xD52834:0x33AA33,(b,g)->t.levels=!t.levels));}
            else{if(t.target!=null || Arrays.asList("kill","stat","achievement","biome","fluid","observation","interaction","gamestage","skill").contains(type))e.add(scalar("target",type.equals("kill")?"entity":"target"));e.add(scalar("count",type.equals("custom")?"max_progress":"value"));if(type.equals("custom")){e.add(scalar("manual","enable_button"));e.add(scalar("checkActive","check"));}if(type.equals("ic2_energy"))e.add(scalar("energyTier","tier"));if(type.equals("botania_mana"))e.add(scalar("showNumbers","show_numbers"));}
        }
        else if(object instanceof QuestCore.Reward){QuestCore.Reward r=(QuestCore.Reward)object;e.add(enumeration("mode","team_reward","inherit","team","individual"));e.add(enumeration("auto","autoclaim","inherit","disabled","enabled","invisible"));if(r.type.equals("item")){e.add(item("item","meta","nbt","item"));e.add(scalar("count","count"));e.add(scalar("randomBonus","random_bonus"));e.add(scalar("onlyOne","only_one"));}else if(r.type.equals("xp") || r.type.equals("xp_levels"))e.add(scalar("count",r.type));else if(r.type.equals("choice") || r.type.equals("random"))e.add(new Entry("FTB Quests",label("rewards"),()->"["+r.options.size()+"]",()->0xAAAAAA,(b,g)->mc.displayGuiScreen(new QuestRewardTableEditScreen(this,draft,r.options,null,()->{}))));else{if(r.type.equals("command")){e.add(scalar("target","command"));e.add(scalar("asPlayer","player"));}else if(r.type.equals("toast")){e.add(scalar("target","title"));e.add(scalar("text","text"));e.add(item("item","meta","nbt","icon"));}else e.add(scalar("target","target"));}}
        else if(object instanceof QuestCore.Chapter){e.add(descriptionList());e.add(scalar("alwaysInvisible","always_invisible"));e.add(scalar("parent","group"));e.add(enumeration("defaultQuestShape","default_quest_shape","","square","rsquare","circle","diamond","pentagon","hexagon","octagon","heart","gear"));}
        else if(object instanceof QuestCore.Book){e.add(emergencyItems());e.add(emergencyTimer());e.add(scalar("dropLootCrates","drop_loot_crates"));e.add(scalar("disableGui","disable_gui"));e.add(scalar("gridScale","grid_scale"));e.add(scalar("defaultRewardTeam","defaults.reward_team"));e.add(scalar("defaultConsumeItems","defaults.consume_items"));e.add(enumeration("defaultAutoClaim","defaults.autoclaim_rewards","disabled","enabled","invisible"));e.add(enumeration("defaultQuestShape","defaults.quest_shape","square","rsquare","circle","diamond","pentagon","hexagon","octagon","heart","gear"));e.add(scalar("hideFromItemBrowser","defaults.quest_disable_jei"));}
        if(has("disableToast"))e.add(scalar("disableToast","disable_completion_toast"));
        if(object instanceof QuestCore.Book){String defaults=tr("ftbquests.file.defaults");for(int i=0;i<e.size();i++)if(Arrays.asList(label("defaults.reward_team"),label("defaults.consume_items"),label("defaults.autoclaim_rewards"),label("defaults.quest_shape"),label("defaults.quest_disable_jei")).contains(e.get(i).label))e.set(i,grouped(e.get(i),defaults));for(String kind:Arrays.asList("passive","monster","boss"))e.add(noDrop(kind));}
        return e;
    }
    private Entry emergencyTimer(){QuestCore.Book book=(QuestCore.Book)object;return new Entry("FTB Quests",label("emergency_items_cooldown"),()->QuestTimer.format(QuestTimer.emergency(book)),()->0xAA5AE8,(b,g)->mc.displayGuiScreen(new QuestValueScreen(this,QuestTimer.format(QuestTimer.emergency(book)),0xAA5AE8,128,text->{long ticks=QuestTimer.parse(text);if(ticks>630720000L)throw new IllegalArgumentException("Duration exceeds one year");book.emergencyCooldownTicks=ticks;})));}
    private Entry emergencyItems(){QuestCore.Book book=(QuestCore.Book)object;return new Entry("FTB Quests",label("emergency_items"),()->"["+book.emergencyItems.size()+"]",()->0x33AA33,(b,g)->{List<ItemStack> items=new ArrayList<ItemStack>();for(QuestCore.Reward reward:book.emergencyItems){ItemStack value=stack(reward.item,reward.meta,reward.nbt);if(value!=null){value.stackSize=reward.count;items.add(value);}}mc.displayGuiScreen(new QuestValueListScreen<ItemStack>(this,label("emergency_items"),items,()->null,value->value==null?tr("ftbquests.null"):value.stackSize+"x "+value.getDisplayName(),(parent,value,accept)->mc.displayGuiScreen(new QuestItemSelectScreen(parent,value,false,v->true,accept)),0x33AA33).onAccepted(()->{book.emergencyItems.clear();for(ItemStack value:items)if(value!=null){QuestCore.Reward reward=new QuestCore.Reward();reward.item=(String)Item.itemRegistry.getNameForObject(value.getItem());reward.meta=value.getItemDamage();reward.nbt=value.hasTagCompound()?value.getTagCompound().toString():"";reward.count=value.stackSize;book.emergencyItems.add(reward);}}));});}
    private Entry grouped(Entry entry,String group){Entry result=new Entry(group,entry.label,entry.value,entry.color,entry.edit);result.info.addAll(entry.info);return result;}
    private Entry noDrop(String kind){QuestCore.Book book=(QuestCore.Book)object;return new Entry(tr("ftbquests.file.loot_crate_no_drop"),tr("ftbquests.loot.entitytype."+kind),()->Integer.toString(kind.equals("passive")?book.noDrop.passive:kind.equals("monster")?book.noDrop.monster:book.noDrop.boss),()->0xAA5AE8,(b,g)->mc.displayGuiScreen(new QuestValueScreen(this,Integer.toString(kind.equals("passive")?book.noDrop.passive:kind.equals("monster")?book.noDrop.monster:book.noDrop.boss),0xAA5AE8,10,v->{int weight=Integer.parseInt(v);if(weight<0 || weight>1000000)throw new IllegalArgumentException("Invalid drop weight");if(kind.equals("passive"))book.noDrop.passive=weight;else if(kind.equals("monster"))book.noDrop.monster=weight;else book.noDrop.boss=weight;})));}
    private Entry dependencies(QuestCore.Quest q){return new Entry("FTB Quests",tr("ftbquests.dependencies"),()->"["+q.dependencies.size()+"]",()->0x0094FF,(b,g)->mc.displayGuiScreen(new QuestValueListScreen<String>(this,tr("ftbquests.dependencies"),q.dependencies,()->"",v->v,(parent,v,accept)->mc.displayGuiScreen(new QuestSelectObjectScreen(parent,QuestSelectObjectScreen.QUEST|QuestSelectObjectScreen.TASK|QuestSelectObjectScreen.CHAPTER,false,s->s.quest==null || !s.quest.id.equals(q.id),s->accept.accept(s.id))),0x0094FF)));}
    List<Entry> quickEntries(){quick=true;List<Entry> result=new ArrayList<Entry>();for(Entry entry:entries()){String value=entry.value.get();if(value.equals("true") || value.equals("false") || entry.color.getAsInt()==0x0094FF && !value.startsWith("["))result.add(entry);}result.sort(java.util.Comparator.comparing(e->e.label,String.CASE_INSENSITIVE_ORDER));return result;}
    @Override protected void save(){
        if(validateAll)draft.validate();else{QuestCore.Book check=QuestService.JSON.fromJson(QuestService.JSON.toJson(draft),QuestCore.Book.class);check.quests.clear();check.chapters.clear();QuestCore.Quest quest=new QuestCore.Quest();quest.id="validation";quest.title="Validation";if(object instanceof QuestCore.Reward)quest.rewards.add((QuestCore.Reward)object);if(object instanceof QuestCore.Task)quest.tasks.add((QuestCore.Task)object);check.quests.add(quest);check.validate();}
        commit.run();
    }
}
